function steps(n) {
  let count = 0;
  for (let i = 1; i < n; i *= 2) count++;
  return count;
}

function hasCommon(a, b) {
  for (const x of a) if (b.includes(x)) return true;
  return false;
}

function letterTable(s) {
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    for (let c = 0; c < 26; c++) {
      if (s.charCodeAt(i) - 97 === c) total++;
    }
  }
  return total;
}

function maxSub(nums) {
  let best = 0, current = 0;
  for (const x of nums) {
    current = Math.max(x, current + x);
    best = Math.max(best, current);
  }
  return best;
}
console.log(maxSub([-8, -3, -6]));

function maxSubarraySum(nums) {
  let best = nums[0];
  let current = nums[0];
  for (let i = 1; i < nums.length; i++) {
    current = Math.max(nums[i], current + nums[i]);
    best = Math.max(best, current);
  }
  return best;
}
