function power(x, n) {
  if (n === 0) return 1;
  if (n % 2 === 0) return power(x, n / 2) * power(x, n / 2);
  return x * power(x, n - 1);
}

function hanoi(n, from, to, via, moves = []) {
  if (n === 0) return moves;
  hanoi(n - 1, from, via, to, moves);
  moves.push(`${from}->${to}`);
  hanoi(n - 1, via, to, from, moves);
  return moves;
}
