function reverseRec(head) {
  if (!head || !head.next) return head;
  const newHead = reverseRec(head.next);
  head.next.next = head;
  head.next = null;
  return newHead;
}

class TwoStackQueue {
  #in = [];
  #out = [];
  enqueue(x) { this.#in.push(x); }
  dequeue() {
    if (this.#out.length === 0)
      while (this.#in.length) this.#out.push(this.#in.pop());
    return this.#out.pop();
  }
}
